import { CoinDetailsScreen } from "@/screens/coin-details-screen";

// A Server Component: it reads the id from the URL here and passes it down,
// so the client screen doesn't need useParams. PageProps is generated by
// `next typegen` from this folder's path.
export default async function CoinPage({ params }: PageProps<"/coins/[id]">) {
  const { id } = await params;
  return <CoinDetailsScreen id={id} />;
}
